          429,
          "RATE_LIMITED",
          "요청 제한 시간 뒤에 다시 시도해 주세요.",
          result == null ? 1 : (int) Math.abs(result));
    trace.step("Redis", "rate_limit", "공유 Redis에서 " + kind + " 제한 원자 검사", "Limiter.reserve");
  }

