async function mutate(kind, b, key, trace) {
  uuid(b.operationId);
  uuid(b.paymentKey);
  if (!key || key.length > 300) fail(400, "KEY_REQUIRED");
  if (
    !Number.isSafeInteger(b.amount) ||
    b.amount < 1 ||
